steps.cmd:
python3 - <<'EOF'
key='KEYWORD'   # <- put the keyword from key.txt here (lowercase)
ct=open('ciphertext.txt').read(); out=[]; ki=0
for c in ct:
    if c.isalpha():
        k=ord(key[ki%len(key)].lower())-97; b=65 if c.isupper() else 97
        out.append(chr((ord(c)-b-k)%26+b)); ki+=1
    else: out.append(c)
print(''.join(out))
EOF
